member.example:
var databaseAttach = new Database(server, dbName);
databaseAttach.FileGroups.Add(new FileGroup(databaseAttach, "PRIMARY"));
databaseAttach.FileGroups["PRIMARY"].Files.Add(new DataFile(databaseAttach.FileGroups["PRIMARY"], primaryName, primaryFileName));
databaseAttach.Create(forAttach:true);

member.summary:
Script out the QDS options for enabling/disabling the feature.
ALTER DATABASE [$(DatabaseName)] SET QUERY_STORE = ON|OFF
{ ALTER DATABASE [$(DatabaseName)] SET QUERY_STORE ( OPERATION_MODE = OFF|READ_ONLY|READ_WRITE , CLEANUP_POLICY = (STALE_QUERY_THRESHOLD_DAYS = ##) , DATA_FLUSH_INTERVALS_SECONDS = ## , INTERVAL LENGTH MINUTES = ## , MAX_STORAGE_SIZE_MB = ## , QUERY_CAPTURE_MODE = ALL|AUTO , SIZE_BASED_CLEANUP_MODE = OFF|AUTO ) }
